🐛 Bug

I am trying to convert the format between cv::Mat and torch::Tensor using c++(libtorch), one crucial step of which is to permute the shape of the Tensor. However I found that in some cases the permute() function failed to manage the memory of the image.
To Reproduce
I provide some code to reproduce the bug:

Image Version

#include <opencv2/opencv.hpp>
#include <torch/script.h>
#include <cstdint>
#include <cstdio>
#include <iostream>

const char* shape_of(torch::Tensor const & tensor) {
  const int kBufferSize = 64;
  static char buffer[kBufferSize];
  memset(buffer, kBufferSize, 0);
  int offset = 0;
  offset += snprintf(buffer+offset, kBufferSize-offset, "(");
  for(int i : tensor.sizes()) {
    offset += snprintf(buffer+offset, kBufferSize-offset, "%d,", i);
  }
  offset += snprintf(buffer+offset-1, kBufferSize-offset, ")");
  return buffer;
}

int main(){
    cv::VideoCapture cap("video.mp4");
    cv::Mat frame, show;
    torch::Tensor tframe, tres;
    cap >> frame;
    tframe = torch::from_blob(frame.data, {1, frame.rows, frame.cols, 3}, torch::kByte);
    tframe = tframe.permute({0,3,1,2}).toType(torch::kFloat).div_(255.0f).to(torch::kCUDA);
    printf("%s,\n", shape_of(tframe));
    tres = tframe.to(torch::kCPU).mul_(255.0f).toType(torch::kByte).permute({0, 2, 3, 1}); // this would not work
    //tres = tframe.permute({0, 2, 3, 1}).to(torch::kCPU).mul_(255.0f).toType(torch::kByte); // this would work!!!
    printf("%s,\n", shape_of(tres));
    show = cv::Mat(frame.rows, frame.cols, CV_8UC3, tres.data<uint8_t>(), frame.cols);
    imshow("show", show);
    imshow("frame", frame);
    cv::waitKey(0);
    return 0;
}

